<script setup lang="ts">
import {ref,watch} from 'vue';import AccountingSelect from './AccountingSelect.vue';import {useAccountingPermissions} from './permissions';
const props=defineProps<{company:number;csrf?:string}>(),emit=defineEmits(['notice']);const can=useAccountingPermissions();const data=ref<any>(null),busy=ref(false),error=ref('');const form=ref({currency:'USD',exchange_rate:'',rate_date:new Date().toLocaleDateString('en-CA')});
async function load(){data.value=null;error.value='';try{const r=await fetch('/accounting/api/currencies?company_id='+props.company,{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.message);data.value=d;}catch(e){error.value=(e as Error).message;}}
watch(()=>props.company,load,{immediate:true});
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const r=await fetch('/accounting/api/currencies',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:JSON.stringify({...form.value,company_id:props.company})});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);emit('notice',d.message);await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><section><div class="ac-section-heading"><div><h2>Currencies & exchange rates</h2><p class="muted">Base currency: {{data?.base||'—'}}. Rates are base-currency units per one foreign unit.</p></div></div><p v-if="error" class="notice admin-error">{{error}}</p><p class="ac-help">Rates are entered by your finance team, not fetched live. Select and verify a dated rate on each transaction. Automatic period-end revaluation is not included; foreign balances retain their historical carrying values until reviewed adjustments are posted. Posted totals remain in the company's base currency.</p><form v-if="can('books.manage')&&data" class="ac-filters" @submit.prevent="save"><label>Currency<AccountingSelect><select v-model="form.currency"><option v-for="c in data.currencies.filter((c:string)=>c!==data.base)" :key="c">{{c}}</option></select></AccountingSelect></label><label>Effective date<input type="date" v-model="form.rate_date" required></label><label>Rate<input v-model="form.exchange_rate" inputmode="decimal" required placeholder="e.g. 282.000000"></label><button class="button primary" :disabled="busy">{{busy?'Saving...':'Save exchange rate'}}</button></form><div v-if="data" class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Currency</th><th>Effective date</th><th>Rate in {{data.base}}</th></tr></thead><tbody><tr v-for="r in data.rates" :key="r.id"><td>{{r.currency}}</td><td>{{r.rate_date}}</td><td>{{r.rate}}</td></tr><tr v-if="!data.rates.length"><td colspan="3">No dated rates saved yet.</td></tr></tbody></table></div></section></template>
